WITH input_tags AS ( SELECT unnest(ARRAY[
#{tagName}
]) AS tag_name ), inserted_tags AS ( INSERT INTO member_tag (owner_member_id, tag_name) SELECT #{memberId}, tag_name FROM input_tags ON CONFLICT (owner_member_id, tag_name) DO UPDATE SET deleted_at = NULL, updated_at = now() RETURNING member_tag_id, tag_name ) SELECT member_tag_id as "memberTagId", tag_name as "tagName" FROM inserted_tags

